async def stream(self, symbol: str | None = None) -> AsyncIterator[Tick]:
    with self.path.open() as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            t = Tick(**json.loads(line))
            if symbol and t.symbol != symbol:
                continue
            yield t
            if self.pace:
                await asyncio.sleep(self.pace)
